import{_ as t,o,c as r,ae as a}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"ADR 029: Enforce HTTPS for Turso (LibSQL)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/029-enforce-https-turso.md","filePath":"adr/029-enforce-https-turso.md"}'),s={name:"adr/029-enforce-https-turso.md"};function i(n,e,c,l,d,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-029-enforce-https-for-turso-libsql" tabindex="-1">ADR 029: Enforce HTTPS for Turso (LibSQL) <a class="header-anchor" href="#adr-029-enforce-https-for-turso-libsql" aria-label="Permalink to &quot;ADR 029: Enforce HTTPS for Turso (LibSQL)&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The application experienced &quot;500 Internal Server Error&quot; responses during Google Login and other database-intensive operations when deployed to Render (Serverless/PaaS env) and even occasionally in local development.</p><p>The root cause was identified as <code>LibsqlError: SQLITE_UNKNOWN: SQLite error: connection not opened</code>. The application was using the <code>libsql://</code> protocol, which establishes a WebSocket connection. In serverless environments (like Render) or during &quot;Scale to Zero&quot; wake-ups, the persistent WebSocket connection was either failing to establish quickly enough or dropping silently, leading to &quot;Connection not opened&quot; errors when the application attempted to execute queries.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to <strong>enforce the HTTPS protocol</strong> for all Turso database connections in the <code>TursoDatabase.ts</code> singleton.</p><p>If the <code>TURSO_DB_URL</code> environment variable is provided as <code>libsql://...</code>, the application now automatically replaces the protocol scheme with <code>https://</code> before creating the client.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Reliability</strong>: HTTP is stateless. Each query is a standalone request. This eliminates &quot;connection invalid&quot; or &quot;socket hung up&quot; errors caused by idle timeouts or serverless freezes.</li><li><strong>Simplicity</strong>: Deployment configuration is robust; it works regardless of whether the user copies the <code>libsql</code> or <code>https</code> URL from the Turso dashboard.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Performance</strong>: HTTP requests may have slightly higher overhead (handshake) compared to a persistent WebSocket connection for high-throughput streaming. However, for a generic CRUD application like TenderCheck AI, this impact is negligible and worth the stability gain.</li><li><strong>No Interactive Transactions</strong>: The HTTP protocol in <code>@libsql/client</code> has limitations regarding interactive transactions compared to WebSockets, but our current usage fits within standard transaction boundaries supported by the HTTP client.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://docs.turso.tech/sdk/ts/reference#supported-protocols" target="_blank" rel="noreferrer">Turso Documentation: Protocols</a></li><li><a href="https://github.com/tursodatabase/libsql-client-ts/issues/..." target="_blank" rel="noreferrer">GitHub Issue: LibsqlError connection not opened</a></li></ul>',17)])])}const b=t(s,[["render",i]]);export{p as __pageData,b as default};
